args.command:
@'
import assert from 'node:assert/strict'
import { createLedger, transfer, getBalance, resetSnapshotCache, createRebateHook } from './src/index.js'

function funded(entries) {
  const ledger = createLedger()
  for (const [account, amountCents] of Object.entries(entries)) {
    ledger.append({ type: 'credit', account, amountCents, ts: 1, id: `fund-${account}` })
  }
  return ledger
}

resetSnapshotCache()
const ledger = funded({ alice: 100, bob: 0 })
const initialTotal = Object.values(ledger.fold()).reduce((sum, value) => sum + value, 0)
for (let i = 0; i < 40; i++) {
  for (const account of ['alice', 'bob', 'missing']) {
    assert.equal(getBalance(ledger, account), ledger.fold()[account] ?? 0)
  }
  const from = i % 2 === 0 ? 'alice' : 'bob'
  const to = from === 'alice' ? 'bob' : 'alice'
  const balance = ledger.fold()[from] ?? 0
  if (balance > 0) transfer(ledger, from, to, Math.min(balance, (i % 7) + 1))
  const folded = ledger.fold()
  assert.equal(Object.values(folded).reduce((sum, value) => sum + value, 0), initialTotal)
  assert.ok(Object.values(folded).every((value) => value >= 0))
}

const hooked = funded({ alice: 10000, bob: 5000 })
transfer(hooked, 'alice', 'bob', 1000, { onSettled: createRebateHook(hooked, 10) })
assert.deepEqual(hooked.fold(), { alice: 9091, bob: 5909 })

const mutated = funded({ alice: 100 })
let calls = 0
assert.throws(() => transfer(mutated, 'alice', 'bob', 80, {
  nextId() {
    calls++
    if (calls === 2) mutated.append({ type: 'debit', account: 'alice', amountCents: 30, ts: 2, id: 'external' })
    return `id-${calls}`
  },
}), /insufficient funds/)
assert.deepEqual(mutated.fold(), { alice: 70 })

console.log('extended invariant checks passed')
